def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata (everything after +)
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split off pre-release (everything after -)
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            identifiers = prerelease.split('.')
            prerelease_parts = []
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease_parts.append((0, int(identifier)))
                else:
                    prerelease_parts.append((1, identifier))
        else:
            prerelease_parts = None

        return (major, minor, patch, prerelease_parts)

    def sort_key(version):
        major, minor, patch, prerelease_parts = parse_version(version)

        # If there's no pre-release, it sorts after the same version with pre-release
        # So we use a tuple where pre-release versions have (0, ...) and release versions have (1, ...)
        if prerelease_parts is None:
            return (major, minor, patch, (1,))
        else:
            return (major, minor, patch, (0,) + tuple(prerelease_parts))

    # Sort with stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

